const rows = $input.first().json.data || [];
const actives = rows.filter(r => !['blacklisted','ignored'].includes(r.statut));
return actives.map(r => ({ json: r }));

const HOURS = 6;               // fenêtre de fraîcheur
const sources = $('Sources actives').all().map(i => i.json);
const st = $getWorkflowStaticData('global');
st.seen = st.seen || {};
let reset = false; try { reset = $('Lancement manuel (webhook)').first().json.query.reset === '1'; } catch (e) {}
if (reset) st.seen = {};
const now = Date.now();
// purge des vidéos vues il y a plus de 7 jours
for (const [k, t] of Object.entries(st.seen)) if (now - t > 7*24*3600e3) delete st.seen[k];
const out = [];
$input.all().forEach((item, idx) => {
  const src = sources[idx];
  const xml = item.json.data || '';
  if (!src || typeof xml !== 'string') return;
  const entries = xml.split('<entry>').slice(1);
  for (const e of entries) {
    const vid = (e.match(/<yt:videoId>([^<]+)<\/yt:videoId>/) || [])[1];
    const pub = (e.match(/<published>([^<]+)<\/published>/) || [])[1];
    if (!vid || !pub) continue;
    const age = now - Date.parse(pub);
    if (age > HOURS*3600e3) continue;
    if (st.seen[vid]) continue;
    st.seen[vid] = now;
    out.push({ json: { video_id: vid, publiee_le: pub, channel_id: src.channel_id, source_nom: src.nom, source_statut: src.statut, categorie: src.categorie } });
  }
});
return out;

const ids = $input.all().map(i => i.json.video_id);
const out = [];
for (let i = 0; i < ids.length; i += 50) out.push({ json: { ids: ids.slice(i, i+50).join(',') } });
return out;

const meta = {};
for (const i of $('Nouvelles vidéos').all()) meta[i.json.video_id] = i.json;
const dur = s => { const m = (s||'').match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/) || []; return (+m[1]||0)*86400 + (+m[2]||0)*3600 + (+m[3]||0)*60 + (+m[4]||0); };
const now = Date.now();
const cands = [];
for (const page of $('Stats YouTube').all()) for (const v of (page.json.items || [])) {
  const m = meta[v.id]; if (!m) continue;
  if (['live','upcoming'].includes(v.snippet.liveBroadcastContent)) continue;
  const h = Math.max(0.25, (now - Date.parse(v.snippet.publishedAt)) / 3600e3);
  const vues = +(v.statistics.viewCount || 0);
  cands.push({ ...m, titre: v.snippet.title, description: (v.snippet.description || '').slice(0, 400),
    duree_s: dur(v.contentDetails.duration), vues, likes: +(v.statistics.likeCount || 0),
    commentaires: +(v.statistics.commentCount || 0), age_h: Math.round(h*10)/10, vues_par_h: Math.round(vues / h) });
}
if (!cands.length) return [];
// ---- Phase d'exploration (200 premiers Shorts) : pas de goûts ni de leçons, la variété est gérée dans « Sélection » ----
const system = `Tu es le rédacteur en chef d'« L’Extrait politique », une chaîne YouTube française qui fait « le zapping des meilleurs moments » de l'actualité : extraits forts (clash, punchline, déclaration choc, contradiction, aveu, moment d'émotion, révélation, analyse éclairante d'un spécialiste).
Tu reçois des vidéos publiées récemment par des médias, institutions, personnalités politiques de tous bords, mais aussi des experts, intellectuels et think tanks (géopolitique, économie, énergie, société). Une analyse de spécialiste qui éclaire ou bouscule l'actualité est un vrai moment fort, au même titre qu'un clash. Note chacune de 0 à 10 selon son potentiel à fournir un moment fort exploitable :
- 9-10 : moment fort évident, sujet chaud, fort potentiel viral ;
- 7-8 : bon potentiel, à regarder ;
- 4-6 : intérêt moyen ;
- 0-3 : routine, contenu sans moment saillant, sujet froid.
Tiens compte de la dynamique (vues par heure rapportées à la taille habituelle de la source), du titre et de la description. Reste neutre politiquement : juge le potentiel éditorial, pas l'opinion exprimée. Pénalise les rumeurs, décès non confirmés et contenus invérifiables.
Pour chaque vidéo propose : le format (« short » ≤ 2 min 30, « long » ~10 min, ou « aucun »), un angle éditorial (15 mots max) et la raison (15 mots max).
Si la source est « watch_only », la vidéo ne peut servir qu'à repérer un sujet (pas d'extrait) : signale-le dans l'angle.
Pour chaque vidéo, étiquette aussi : personnes (qui s'exprime ou dont on parle, noms complets, max 3), type_intervenant (politique, expert, journaliste, citoyen, autre), camp (LFI, PS, Écologistes, PCF, extrême gauche, Renaissance/centre, LR, RN, Reconquête, souverainistes, gouvernement, institutions, plusieurs camps, non partisan — « non partisan » pour les experts, journalistes et citoyens sans étiquette), theme (court et normalisé : sécurité, éducation, budget/dette, immigration, justice, international, institutions, social, féminisme, médias…), type_moment (clash, punchline, déclaration, aveu, contradiction, témoignage, chiffre choc, manifestation, analyse, annonce).
Réponds UNIQUEMENT avec un tableau JSON : [{"video_id":"...","score":0,"format":"short|long|aucun","angle":"...","raison":"...","personnes":["..."],"type_intervenant":"...","camp":"...","theme":"...","type_moment":"..."}]` ;
const out = [];
for (let i = 0; i < cands.length; i += 20) {
  const lot = cands.slice(i, i + 20);
  const user = JSON.stringify(lot.map(c => ({ video_id: c.video_id, source: c.source_nom, categorie: c.categorie, statut_source: c.source_statut, titre: c.titre, description: c.description, duree_s: c.duree_s, vues: c.vues, vues_par_h: c.vues_par_h, age_h: c.age_h, likes: c.likes, commentaires: c.commentaires })));
  out.push({ json: { candidats: lot, body: { model: 'claude-sonnet-4-5', max_tokens: 3000, system, messages: [{ role: 'user', content: user }] } } });
}
return out;

const SEUIL = 7, MAX = 8;
const cands = $('Préparer candidats').all().flatMap(i => i.json.candidats);
let notes = [];
for (const it of $input.all()) {
  const txt = (it.json.content || []).map(c => c.text || '').join('');
  try { notes.push(...JSON.parse(txt.slice(txt.indexOf('['), txt.lastIndexOf(']') + 1))); } catch (e) { /* lot illisible ignoré */ }
}
if (!notes.length) throw new Error('Aucune note exploitable renvoyée par Claude');
const byId = Object.fromEntries(notes.map(n => [n.video_id, n]));
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const fmtDur = s => s >= 3600 ? `${Math.floor(s/3600)}h${String(Math.floor(s%3600/60)).padStart(2,'0')}` : `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
const fmtN = n => n >= 1e6 ? (n/1e6).toFixed(1)+' M' : n >= 1e3 ? Math.round(n/1e3)+' k' : String(n);
const deja = new Set(($('Lire historique décisions').first().json.data || []).map(r => r.video_id));
const top = cands.filter(c => !deja.has(c.video_id)).map(c => ({ ...c, ...(byId[c.video_id] || { score: 0 }) }))
  .filter(c => c.score >= SEUIL).sort((a, b) => b.score - a.score || b.vues_par_h - a.vues_par_h).slice(0, MAX);
// ---- Choix autonome : 1 Short à la fois (créneaux de 3 h), choisi entre 7h et 22h, si la file n'est pas engorgée ----
// ---- Choix autonome en PHASE D'EXPLORATION : 1 Short à la fois (créneaux de 3 h), entre 7h et 22h ----
// But : collecter des données variées (sujets, intervenants, camps, chaînes, types de moments) avant les premières analyses à 200 Shorts.
const SEUIL_AUTO = 7;
const heure = +new Date().toLocaleString('en-GB', { hour: '2-digit', hour12: false, timeZone: 'Europe/Paris' });
const tNow = Date.now();
const histo = $('Lire historique décisions').first().json.data || [];
const enCours = histo.filter(r =>
  (r.statut === 'planifiee' && Date.parse(r.publication_prevue) > tNow) ||
  (['en_production', 'extrait_pret', 'extrait_valide'].includes(r.statut) && tNow - Date.parse(r.updatedAt || r.decision_le || 0) < 2 * 3600e3)).length;
// Shorts récents (publiés + choisis pas encore publiés), du plus récent au plus ancien
const norm = s => String(s || '').toLowerCase().trim();
const pub = ($('Lire Shorts récents').first().json.data || []).map(r => ({ t: Date.parse(r.publiee_le), source: r.chaine, theme: r.theme, camp: r.camp, pers: r.intervenant, ti: r.type_intervenant }));
const pubIds = new Set(($('Lire Shorts récents').first().json.data || []).map(r => r.video_id));
const choisis = histo.filter(r => r.decision === 'choix_ia' && !pubIds.has(r.video_id) && r.statut !== 'abandonnee')
  .map(r => ({ t: Date.parse(r.decision_le || 0), source: r.source_nom, theme: r.theme, camp: r.camp, pers: r.personnes, ti: '' }));
const recents = [...choisis, ...pub].sort((a, b) => b.t - a.t);
const last = k => recents.slice(0, k);
const cnt = (arr, f, val) => arr.filter(x => norm(x[f]) && norm(x[f]) === norm(val)).length;
const variete = c => {
  let adj = 0; const raisons = [];
  const p1 = String((Array.isArray(c.personnes) ? c.personnes[0] : String(c.personnes || '').split(',')[0]) || '').trim();
  if (cnt(last(3), 'source', c.source_nom)) { adj -= 1.5; raisons.push('même chaîne récemment'); }
  const th = Math.min(2, cnt(last(3), 'theme', c.theme)); if (th) { adj -= th; raisons.push('thème déjà traité'); }
  const cp = Math.min(2, cnt(last(3), 'camp', c.camp)); if (cp) { adj -= cp; raisons.push('camp déjà traité'); }
  if (p1 && last(5).some(x => norm(x.pers).includes(norm(p1)))) { adj -= 2; raisons.push('intervenant déjà vu'); }
  let bonus = 0;
  if (c.theme && !cnt(last(30), 'theme', c.theme)) { bonus++; raisons.push('thème jamais testé'); }
  if (c.camp && !cnt(last(30), 'camp', c.camp)) { bonus++; raisons.push('camp jamais testé'); }
  if (c.source_nom && !cnt(last(30), 'source', c.source_nom)) { bonus++; raisons.push('chaîne jamais testée'); }
  if (c.type_intervenant && c.type_intervenant !== 'politique' && !cnt(last(10), 'ti', c.type_intervenant)) { bonus++; raisons.push(c.type_intervenant + ' peu testé'); }
  adj += Math.min(2, bonus);
  return { adj, raisons };
};
const eligibles = (heure >= 7 && heure < 22 && enCours === 0)
  ? top.filter(c => c.score >= SEUIL_AUTO && c.source_statut === 'usable' && c.format !== 'aucun' && c.duree_s >= 20)
      .map(c => { const v = variete(c); return { ...c, note_explo: c.score + v.adj, raisons_explo: v.raisons }; })
      .sort((a, b) => b.note_explo - a.note_explo || b.vues_par_h - a.vues_par_h)
  : [];
const elu = eligibles[0] || null;
return top.map(c => ({ json: { ...c, auto: !!elu && c.video_id === elu.video_id, explo: elu && c.video_id === elu.video_id ? `🧭 Exploration : ${elu.raisons_explo.length ? elu.raisons_explo.join(', ') : 'meilleure note'} (note ${c.score} → ${Math.round(elu.note_explo * 10) / 10})` : '',
  texte: `🎬 <b>${esc(c.titre)}</b>\n📺 ${esc(c.source_nom)}${c.source_statut === 'watch_only' ? ' <i>(sujet seulement, pas d\'extrait)</i>' : ''}\n⏱ ${fmtDur(c.duree_s)} · 👁 ${fmtN(c.vues)} vues · il y a ${c.age_h} h\n⭐ <b>${c.score}/10</b> · Format : ${esc(c.format)}\n💡 <b>Angle :</b> ${esc(c.angle)}\n🧠 ${esc(c.raison)}\n🔗 https://youtu.be/${c.video_id}`,
  cb_ok: `ok|${c.video_id}`, cb_no: `no|${c.video_id}`, cb_src: `src|${c.video_id}|${c.channel_id}` } }));
